import 'jest';
import { camelCaseResponseConverter } from '../../src';

describe('camelCaseResponseConverter()', () => {
    test('convert an objects properties to be camelCase', () => {
        expect(camelCaseResponseConverter({
            test: 0,
            TestProperty: 1,
            TestPropertyTwo: 2
        })).toEqual({
            test: 0,
            testProperty: 1,
            testPropertyTwo: 2
        });
    });
});